window.STORY_CHAPTERS["c376d12a0aedd15f2"]={"id":"c376d12a0aedd15f2","lines":[{"uid":"talk.event_1_01#originalText","id":"talk.event_1_01","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我要用我家祖传的赛鲁鲁特流剑法成为最强的剑士！","en":"In the name of my family’s Serlut style, I will become stronger!","ja":"我が家に伝わるセルルト流で私は最強の剣士になってみせます!"},"kind":"dialogue"},{"uid":"talk.event_1_02#originalText","id":"talk.event_1_02","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"赛鲁鲁特流…果然是非主流吗","en":"It has to be...  Are they weak against the Serlut style?","ja":"やはり……セルルト流は搦め手なのでしょうか"},"kind":"dialogue"},{"uid":"talk.event_1_03#originalText","id":"talk.event_1_03","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"赛菲利雅花的种子有股好香的味道。那是什么样的花呢。","en":"The Zephyria seed had a beautiful scent.  I wonder what kind of flower it is.","ja":"ゼフィリアの種、いい香りだったなぁどんな花なんだろう"},"kind":"dialogue"},{"uid":"talk.event_1_04#originalText","id":"talk.event_1_04","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我索尔缇莉娜‧赛鲁鲁特要为了自己变得更强！","en":"I, Sortiliena Serlut, will become stronger for myself!","ja":"私ソルティリーナ・セルルトは自分自身のために、強くなります!"},"kind":"dialogue"},{"uid":"talk.event_1_05#originalText","id":"talk.event_1_05","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"桐人吗……真是个有趣的家伙","en":"Kirito, huh...?  He certainly is interesting.","ja":"キリトか……アイツは面白いやつだな"},"kind":"dialogue"},{"uid":"talk.event_1_06#originalText","id":"talk.event_1_06","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"关于《艾恩葛朗特流》似乎还有一些我不知道的事呢","en":"There’s still much for me to learn about the Aincrad style.","ja":"《アインクラッド流》にはまだ私の知らないことがありそうだな"},"kind":"dialogue"},{"uid":"talk.event_1_07#originalText","id":"talk.event_1_07","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我绝对不能输给和桐人平手的那家伙！","en":"Kirito’s match may have ended in a draw,  but I won’t lose!","ja":"キリトが引き分けたヤツに私が負けるわけにはいかない!"},"kind":"dialogue"},{"uid":"talk.event_1_08#originalText","id":"talk.event_1_08","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"谢谢多亏了你我才能获胜","en":"Thank you.  I couldn’t have won without you.","ja":"ありがとうおかげで私は勝つことができた"},"kind":"dialogue"},{"uid":"talk.event_1_09#originalText","id":"talk.event_1_09","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"再来就是北帝国剑武大会了我今后也不能输！","en":"Next is the Norlangarth Imperial Swordsmanship Tournament.  I won’t be defeated!","ja":"次は北帝国剣武大会だここから先も負けられない!"},"kind":"dialogue"},{"uid":"talk.event_1_10#originalText","id":"talk.event_1_10","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"这就是赛菲利雅花吗好香又好漂亮……呵呵","en":"So this is the Zephyria flower. Beautiful and has such a wonderful scent... Hehe.","ja":"これがゼフィリアの花か……いい香りだし、美しい……ふふっ"},"kind":"dialogue"},{"uid":"talk.event_2_01#originalText","id":"talk.event_2_01","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"呵呵呵，不知道桐人学长有没有好好收拾房间呢……去打扫真让人开心。","en":"Hehehe! I wonder if I will clean the room with Kirito... Looking forward to this.","ja":"ふふふ、キリト先輩ちゃんとお部屋の片付けしてるかな……お掃除に行くの、楽しみだな"},"kind":"dialogue"},{"uid":"talk.event_2_02#originalText","id":"talk.event_2_02","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天的练习好像是和罗妮耶她们共同进行的，跟平常不太一样。不知道是怎样的练习呢……","en":"It looks like for today's practice, the training is going to be different than what we usually do. I wonder what kind of practice it will be...","ja":"今日の稽古はロニエたちと合同でいつもと違う訓練を行うみたいですどんな稽古なんだろう……"},"kind":"dialogue"},{"uid":"talk.event_2_03#originalText","id":"talk.event_2_03","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"用真剑认真进行点到即止的练习，感觉在看的这边心脏也快要停止了……","en":"Even if it is a practice fight, watching them go all out with real swords is enough to make my heart stop…","ja":"実剣で本気の寸止めの試合だなんて見ているこちらの心臓が止まりそう……"},"kind":"dialogue"},{"uid":"talk.event_2_04#originalText","id":"talk.event_2_04","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我从小时候就一直学剑，但像学长们那么精湛的剑技，我至今也从没见过！！","en":"I have been studying the sword ever since I was a little girl. Yet I have never seen such impressive sword technique as yours!!","ja":"小さい頃から剣を習っていますが先輩たちのような見事な剣技は今まで見たことありませんでした!!"},"kind":"dialogue"},{"uid":"talk.event_2_05#originalText","id":"talk.event_2_05","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长们的观摩会……那个时候，学长们的剑好像都变大了……！！","en":"Your perception practice... Of course! Your swords got so big then!!","ja":"先輩たちの見取り稽古……あの時たしかに、先輩たちの剣が大きくなったんです……!!"},"kind":"dialogue"},{"uid":"talk.event_2_06#originalText","id":"talk.event_2_06","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"如果有一天可以跟尤吉欧学长那样，和像是成为了自己一部份的剑相遇就好了……","en":"Someday, I hope I can find a beautiful blade that can become a part of me, just like Eugeo...","ja":"いつかユージオ先輩みたいに自分の一部になるような素敵な剣と出会えたらいいな……"},"kind":"dialogue"},{"uid":"talk.event_2_07#originalText","id":"talk.event_2_07","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"如果可以和学长们一起出去冒险，我想一定会很开心吧……","en":"Going on an adventure with you would be a real blast...","ja":"先輩と一緒に冒険に行けたらきっとすっごく楽しいだろうな……"},"kind":"dialogue"},{"uid":"talk.event_2_clear1#originalText","id":"talk.event_2_clear1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"竟然可以连续重复地使出招式，跟我至今学习的剑术思想完全不同……","en":"Seeing you continue to use that sword technique repeatedly... I feel like it's completely different from everything I've learned and thought about...","ja":"あんなに続けて技を繰り出せるなんて今まで学んできた剣術とは思想からして全く違う気がします……"},"kind":"dialogue"},{"uid":"talk.event_2_clear2#originalText","id":"talk.event_2_clear2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"看了桐人学长们的比试，我对艾恩葛朗特流更加着迷了！！","en":"Kirito and Eugeo’s match was so phenomenal. I was completely captivated by their Aincrad Style! ","ja":"キリト先輩たちの立ち合いを見てますますアインクラッド流に魅せられてしまいました!!"},"kind":"dialogue"},{"uid":"talk.event_2_clear3#originalText","id":"talk.event_2_clear3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我想跟尤吉欧学长使用同一流派，变得更强……","en":"I also want get stronger with the same style as Eugeo's...","ja":"ユージオ先輩と同じ流派で私も強くなりたい……"},"kind":"dialogue"},{"uid":"talk.event_3_01#originalText","id":"talk.event_3_01","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"为了成为集成骑士，我可不能停留在帝国剑武大会。","en":"If you're aiming to become an Integrity Knight, then you can't afford to mess up in the Imperial Swordsmanship Tournament.","ja":"整合騎士を目指すからには帝国剣武大会などでつまずくわけにいかないな"},"kind":"dialogue"},{"uid":"talk.event_3_02#originalText","id":"talk.event_3_02","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"艾恩葛朗特流跟赛鲁鲁特流吗……修剑学院竟然有这么强的人在，真不能大意。","en":"The Aincrad style and Serlut style... You have to be on your guard against such strong characters being at the Swordcraft Academy.","ja":"アインクラッド流とセルルト流か……修剣学院にあんな強者がいたとは油断禁物だな"},"kind":"dialogue"},{"uid":"talk.event_3_03#originalText","id":"talk.event_3_03","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我可是有不可以输的理由，统一大会也一定要赢！！","en":"There's a reason why I can't lose. I'll win for sure, even in the Unification Tournament!","ja":"私には、負けられない理由がある統一大会でも必ずや優勝してみせる!!"},"kind":"dialogue"},{"uid":"talk.event_3_04#originalText","id":"talk.event_3_04","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"只要驱逐了暗之军队，一定不会再有人患上妈妈那种病才对。","en":"If we can drive out the forces of darkness, then people won't get sick like my mother anymore.","ja":"闇の軍勢を駆逐すればきっと母さんのような病に侵される人もいなくなるだろう"},"kind":"dialogue"},{"uid":"talk.event_3_05#originalText","id":"talk.event_3_05","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"首先赢了一场，不算什么。也就是说在帝国剑武大会遇上的那位小姐是拥有很强实力的人吧。","en":"The first victory is not a big deal. The girl that I went up against at the Imperial Swordcraft Tournament was quiet the bigwig.","ja":"まずは一勝、大したことなかったな帝国剣武大会で立ち合った女性がかなりの実力者だったということか"},"kind":"dialogue"},{"uid":"talk.event_3_06#originalText","id":"talk.event_3_06","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"太好了，妈妈！我在统一大会也胜出了！！我终于能成为集成骑士了……！！","en":"I finally did it mother! I won the Unification Tournament! I can finally be an Integrity Knight...!","ja":"やったよ母さん! 統一大会も優勝だ!!ついに整合騎士の職に就くことができるんだ……!!"},"kind":"dialogue"},{"uid":"talk.event_3_clear1#originalText","id":"talk.event_3_clear1","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"留下生病的母亲真的让我有点担心……在任务与任务之间一有时间，就尽可能回来见面吧。","en":"Leaving my sick mother behind worries me... I'll make sure to come visit in between my duties.","ja":"病気の母さんを置いていくのは心配だな……任務の合間を縫ってできるだけ会いに来よう"},"kind":"dialogue"},{"uid":"talk.event_3_clear2#originalText","id":"talk.event_3_clear2","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"要尽快将黑暗领域的恶鬼们驱逐出去，让人们安心地生活下去。","en":"I'll quickly drive out those demons from the Dark Territory, so that people can finally live in peace.","ja":"一刻も早くダークテリトリーの悪鬼どもを駆逐して、人々が安心して暮らせるようにするんだ"},"kind":"dialogue"},{"uid":"talk.event_3_clear3#originalText","id":"talk.event_3_clear3","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"如果是公理教会的话，说不定会有对病和药很清楚的修女。妈妈的病也说不定……","en":"If it's the Axiom Church, there are probably some trainee nuns knowledgable about medicine and diseases. Maybe even about my mother's illness...","ja":"公理教会なら病や薬に詳しい修道女がいるかもしれない母さんの病気ももしかしたら……"},"kind":"dialogue"},{"uid":"talk.event_4_01#originalText","id":"talk.event_4_01","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"没有天界时的记忆真的是很不方便。虽然最高司祭大人说过这也是必须的措施……","en":"It's such a nuissance not having any memories of the heavens. The High Pontifex did say that this was a necessary measure, but...","ja":"天界での記憶がないというのは不便極まりないな。最高司祭様はこれも必要な措置とおっしゃるが……"},"kind":"dialogue"},{"uid":"talk.event_4_02#originalText","id":"talk.event_4_02","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我们可是在天界被召唤下来光荣的集成骑士……那位女性骑士无礼也要有个限度！！","en":"As Integrity Knights, even though we can boast that we were summoned from the heavens... That female Knight is rude beyond repair!","ja":"我らは天界より召喚されし誇りある整合騎士だというのに……あの女性騎士は不躾にもほどがある!!"},"kind":"dialogue"},{"uid":"talk.event_4_03#originalText","id":"talk.event_4_03","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"对着那位女性骑士我竟如此无力……要是受到这以上的屈辱我绝不能原谅自已！！钻研剑技……除此以外，别无他选。","en":"I can't sick my teeth into that female Knight... I will not tolerate any more blunders! Train your swords... And nothing else.","ja":"あの女性騎士に歯が立たぬとは……これ以上の不覚は断じて許されぬ!!剣技を磨く……それ以外にあるまい"},"kind":"dialogue"},{"uid":"talk.event_4_04#originalText","id":"talk.event_4_04","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"搞什么？！那个小子！！真大的口气！！真气人！！","en":"What is this?! That youngster! Such an awful attitude! I can't take it anymore!","ja":"ちょっとなんなの!? あの若造!!ずいぶんな態度じゃない!!あったまくる!!"},"kind":"dialogue"},{"uid":"talk.event_4_05#originalText","id":"talk.event_4_05","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"……竟然被那种小姑娘超越了。我的剑法可真不够成熟啊……要更加钻研剑技才行……！！","en":"... To be beaten by such a young girl. My sword skills are still lacking... I'll have to get better, I will get better...!","ja":"……あんな小娘に後れを取るとは私の剣もまだまだ未熟だ……もっと剣技を磨いて必ずや……!!"},"kind":"dialogue"},{"uid":"talk.event_4_06#originalText","id":"talk.event_4_06","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我从天界被召唤下来一定是为了要保护像爱丽丝阁下这样的人……！！","en":"My summoning from the heavens is by all odds, no different than protecting someone like Alice...!","ja":"私が天界より召喚されたのはきっとアリス殿のような方をお護りするために違いない……!!"},"kind":"dialogue"},{"uid":"talk.event_4_07#originalText","id":"talk.event_4_07","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"能受爱丽丝大人赐教，是我的荣幸……！！","en":"Especially looking up to Alice brings me so much joy...!","ja":"アリス様に師事することこそ我が喜び……!!"},"kind":"dialogue"},{"uid":"talk.event_4_clear1#originalText","id":"talk.event_4_clear1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"艾尔多利耶和伊迪丝阁下他们很合得来吧？感觉他们很要好。","en":"I wonder if Eldrie and Eydis are getting along? They always seem to be close.","ja":"エルドリエとイーディス殿は気が合うのでしょうかいつも仲が良さそうです"},"kind":"dialogue"},{"uid":"talk.event_4_clear2#originalText","id":"talk.event_4_clear2","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"敬爱的吾师爱丽丝大人……要是觉得伊迪丝阁下烦人的话，我随时可以把她给赶走。","en":"My sincere teacher, Alice... If that Eydis starts to get a little annoying, don't hesitate to ask me to drive her away.","ja":"敬愛する我が師、アリス様……イーディス殿がしつこいようであればいつでもこの私が追い払ってみせます"},"kind":"dialogue"},{"uid":"talk.event_4_clear3#originalText","id":"talk.event_4_clear3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"艾尔多利耶那家伙，总是缠着爱丽丝……爱丽丝可是我的妹妹呀！！","en":"That Eldrie is always mixing up with Alice... It's because Alice is my little sister!","ja":"エルドリエのやつ、いっつもアリスに絡んでるわね……アリスはあたしの妹なんだから!!"},"kind":"dialogue"},{"uid":"talk.event_5_01#originalText","id":"talk.event_5_01","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呐，在这边世界的桐人是怎样的？","en":"Hey, how was the Kirito here?","ja":"ねえ、こっちでのキリトくんはどんな感じだったのかしら?"},"kind":"dialogue"},{"uid":"talk.event_5_02#originalText","id":"talk.event_5_02","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"黑色外套……难道是SAO的……？","en":"A black cloak... Could it be, you're from SAO...?","ja":"黒い外套……それってもしかしてあの時の……?"},"kind":"dialogue"},{"uid":"talk.event_5_03#originalText","id":"talk.event_5_03","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"原来如此。桐人的二刀流是在别的世界练成的呀。","en":"I see. So Kirito's Two-sword Style was cultivated in another world.","ja":"なるほどキリトの二刀流は別の世界で培われたものだったのですね"},"kind":"dialogue"},{"uid":"talk.event_5_04#originalText","id":"talk.event_5_04","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"说起来，桐人在毕业典礼那天把肩膀借给我了呢。……嘻嘻。","en":"Speaking of which, Kirito lent me a hand on the day of the graduation ceremony. ...Hehe","ja":"そういえばキリトは卒業式の日に私に肩を貸してくれたな……ふふっ"},"kind":"dialogue"},{"uid":"talk.event_5_05#originalText","id":"talk.event_5_05","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"桐人学长曾经悉心照顾了患上感冒而睡着的我！嘻嘻……","en":"Kirito helped nurse me when I was fast asleep from my cold! Ehhh...","ja":"キリト先輩は、風邪で寝込んでいた私の看病もしてくださったんです!えへへ……"},"kind":"dialogue"},{"uid":"talk.event_5_06#originalText","id":"talk.event_5_06","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要是桐人说要留在这个世界的话，那我应该……","en":"What would I do if Kirito said he wanted to stay in this world...?","ja":"もしもキリトくんがこの世界に残ると言ったらその時わたしは……"},"kind":"dialogue"},{"uid":"talk.event_5_07#originalText","id":"talk.event_5_07","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"桐人……我们会做好我们能做的事。","en":"Kirito... We will do everything that we can do!","ja":"キリト……私たちは私たちのできることをします"},"kind":"dialogue"},{"uid":"talk.event_5_clear2#originalText","id":"talk.event_5_clear2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"跟桐人学长结婚……嘻嘻。……啊！不、不是，什、什么事都没有！！","en":"Getting married to Kirito... Ehhh... Eek! N-No i-it's nothing!","ja":"キリト先輩と結婚……えへへ……あっ! い、いえな、なんでもないです!!"},"kind":"dialogue"},{"uid":"talk.event_5_clear3#originalText","id":"talk.event_5_clear3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"大家也相信着桐人，向前迈进呢。呵呵，你果然是英雄呀。","en":"Seeing everyone trust in Kirito and try to move forward... Hehe. He really is a hero.","ja":"皆、キリトくんのことを信じて前へ進んでいこうとしているふふっ、君はやっぱり英雄だよ"},"kind":"dialogue"},{"uid":"talk.event_6_01#originalText","id":"talk.event_6_01","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天的祭典很热闹呢！","en":"Looks like today's festival is still lively!","ja":"今日のお祭りまだまだ盛り上がっているな!"},"kind":"dialogue"},{"uid":"talk.event_6_02#originalText","id":"talk.event_6_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这水果和那边的蛋糕全都带回去给赛鲁卡好了。","en":"Let's bring home fruit and that cake over there for Selka and the others!","ja":"果物と、あそこのケーキをセルカたちに持って帰ってあげよう"},"kind":"dialogue"},{"uid":"talk.event_6_03#originalText","id":"talk.event_6_03","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"Underworld的创世神话吗……很让人兴奋呢。","en":"A Underworld Myth... I get excited just thinking about it.","ja":"アンダーワールドの創世神話か……なんかワクワクするな"},"kind":"dialogue"},{"uid":"talk.event_6_04#originalText","id":"talk.event_6_04","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"桐人、尤吉欧……你们一定要和姊姊三个人一起回来喔……","en":"Kirito, Eugeo... I want you both to come back... The three of you with her... ","ja":"キリト、ユージオ......絶対に姉さまと3人で帰ってきてね......"},"kind":"dialogue"},{"uid":"talk.event_6_05#originalText","id":"talk.event_6_05","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"可恶……那家伙……明明只要那家伙不在就不会有这样的事了……","en":"Dammit... If he...  He was here, things wouldn't have turned out like this...","ja":"キリト、覚えた？三神はステイシア様テラリア様にソルス様よ"},"kind":"dialogue"},{"uid":"talk.event_6_06#originalText","id":"talk.event_6_06","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔喔！原来可以利用热素加热食物。下次试试看吧！","en":"Hey! Next time, let's try and heat up food with thermal!","ja":"おお! 熱素で食べ物を温められるのか今度試してみるか!"},"kind":"dialogue"},{"uid":"talk.event_6_clear1#originalText","id":"talk.event_6_clear1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"赛鲁卡真厉害。竟然可以把创世神话说得那么有趣。","en":"Selka is amazing!  She sure knows how to tell that creation myth!","ja":"セルカはすごいな創世神話をあんなに楽しく教えてくれるなんて"},"kind":"dialogue"},{"uid":"talk.event_6_clear2#originalText","id":"talk.event_6_clear2","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"桐人、尤吉欧，待你们回来，我会做大餐慰劳你们的。","en":"When Kirito and Eugeo come back, I'll be sure to treat them to something exceptional!","ja":"キリト、ユージオ帰ってきたらとびきりのごちそうを振る舞ってあげるわね"},"kind":"dialogue"},{"uid":"talk.event_7_01#originalText","id":"talk.event_7_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊～今天也好无聊喔。一个人当警卫好无聊呀～","en":"Guessing today will also be boring. Going on patrol by yourself sure is boring...","ja":"あーあ、今日も退屈だなあひとりで警備なんてつまらないなー"},"kind":"dialogue"},{"uid":"talk.event_7_02#originalText","id":"talk.event_7_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"难、难道说那些家伙打算在墙壁下挖个洞攻过来吗！？","en":"Surely they aren't planning on digging under the wall to attack, are they?!","ja":"ま、まさかあの連中壁の下に穴掘って攻めてくる気!?"},"kind":"dialogue"},{"uid":"talk.event_7_03#originalText","id":"talk.event_7_03","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我常常觉得跟元老长沟通不了……","en":"The Prime Senator won't listen...","ja":"元老長ってなんかこう話が通じないのよね……"},"kind":"dialogue"},{"uid":"talk.event_7_04#originalText","id":"talk.event_7_04","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"如果能请四帝国的骑士团来当人界护卫就好了。","en":"I wish we could request protection of the Human Empire from the Imperial Knights of the Four Empires.","ja":"四帝国の騎士団にも人界警護を要請できたらいいんだがなぁ"},"kind":"dialogue"},{"uid":"talk.event_7_05#originalText","id":"talk.event_7_05","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"黑暗界的那些家伙低等的也不过如此嘛。","en":"Those underlings from the Dark World are just small fry.","ja":"暗黒界の連中も下っ端は大したことないわねぇ"},"kind":"dialogue"},{"uid":"talk.event_7_06_1#originalText","id":"talk.event_7_06_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那个女的比我想像中强呢。明明莉琵雅这个名字这么可爱！","en":"That girl is stronger than I thought! You never would have guessed with such a cute name like Lippia!","ja":"思ったより強いわね、あの女リピアなんてかわいい名前なのに!"},"kind":"dialogue"},{"uid":"talk.event_7_06_2#originalText","id":"talk.event_7_06_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"骑士长看起来好像很开心。是跟夏斯达那家伙打了一场吗。","en":"The Knight Commander seems to be having a bit of fun, trading swipes with that Shasta fellow.","ja":"騎士長なんだか楽しそうねシャスターって奴と剣を交えるの"},"kind":"dialogue"},{"uid":"talk.event_7_clear1#originalText","id":"talk.event_7_clear1","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"夏斯达那家伙，实力又进步了。","en":"Damn that Shasta, he's gotten even better than before.","ja":"シャスターの野郎また腕を上げていやがったぜ"},"kind":"dialogue"},{"uid":"talk.event_7_clear2#originalText","id":"talk.event_7_clear2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那个人挺厉害的嘛。莉琵雅吗……我记住了。","en":"That was pretty good. Lippia... was it? I'll remember that.","ja":"なかなかやるじゃない、あの子リピアね……覚えておくわ"},"kind":"dialogue"},{"uid":"talk.event_8_01#originalText","id":"talk.event_8_01","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"我要尽快从见习骑士毕业进入暗黑骑士团……！！","en":"I'll graduate a day faster and prove I can join the Dark Knights…!","ja":"1日でも早く騎士見習いを卒業して暗黒騎士団に入ってみせる……!!"},"kind":"dialogue"},{"uid":"talk.event_8_02#originalText","id":"talk.event_8_02","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"我才不会在意那些无聊家伙的闲言闲语！！","en":"Like I care what a bunch of fools have to say!","ja":"くだらん連中の減らず口なんか気にしてなるものか!!"},"kind":"dialogue"},{"uid":"talk.event_8_03#originalText","id":"talk.event_8_03","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"要更加、更加的得到力量……因为弱者是没办法生存下去！","en":"I need to get even stronger...  Because it's the weak who don't survive!","ja":"もっともっと力をつけなくては......弱ければ生き抜けないのだから!"},"kind":"dialogue"},{"uid":"talk.event_8_04#originalText","id":"talk.event_8_04","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"因为是女人而小看我的就算是暗黑骑士团团长我也绝不原谅！！","en":"I won't forgive anyone who looks down on me for being a woman! Not even the Commander of the Dark Knights!","ja":"女だからと侮ることは暗黒騎士団の長でも絶対に許さん!!"},"kind":"dialogue"},{"uid":"talk.event_8_05#originalText","id":"talk.event_8_05","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"来吧，莉琵雅！想知道我的强弱，就用那把剑来问我！！","en":"Lippia! Come find out if I am weak or not with that sword of yours!","ja":"さあ、リピア!俺が弱いかどうかその剣で俺に問え!!"},"kind":"dialogue"},{"uid":"talk.event_8_06_1#originalText","id":"talk.event_8_06_1","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"为了阁下，我会变得更加、更加的强！！","en":"Even for you, my Lord, I'll prove how strong I can be!","ja":"閣下のためにも私はもっともっと強くなってみせる!!"},"kind":"dialogue"},{"uid":"talk.event_8_06_2#originalText","id":"talk.event_8_06_2","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"我果然没看走眼，妳能够好好理解我说的话，为之担忧，把妳放在身边果真没错。","en":"Just as I suspected, this wasn't bad judgement on my part.  You understand and worry about me.  I am glad I kept you around.","ja":"やはり俺の目に狂いはなかった俺の話を理解し、共に憂えてくれるお前を側に置いてよかった"},"kind":"dialogue"},{"uid":"talk.event_8_clear1#originalText","id":"talk.event_8_clear1","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"阁下的话，一定可以实现到无人受苦的世界。","en":"I believe that your Lord will bring about a fair world for everybody.","ja":"閣下ならば誰も虐げられない世界を実現してくださるはず"},"kind":"dialogue"},{"uid":"talk.event_8_clear2#originalText","id":"talk.event_8_clear2","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"记得小心集成骑士，莉琵雅。说不定「那家伙」也会出现。","en":"Be careful of the Integrity Knights, Lippia. \"He\" will most likely appear.","ja":"整合騎士には気をつけろ、リピア恐らく「ヤツ」が出てくることも考えられる"},"kind":"dialogue"},{"uid":"talk.event_31_01#originalText","id":"talk.event_31_01","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"真是的……竟然有享受PK的中队存在，不可原谅！","en":"Tch… I can't believe there's a squadron who enjoys PK. I won't have it!","ja":"全く......PKを楽しむスコードロンがいるなんて許せないわ!"},"kind":"dialogue"},{"uid":"talk.event_31_02#originalText","id":"talk.event_31_02","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"哼，就没有人能让我更兴奋吗？","en":"Hmph... Is there no other group who can further entertain me?","ja":"ふう、もっと楽しませてくれるような連中はいねえのか?"},"kind":"dialogue"},{"uid":"talk.event_31_03#originalText","id":"talk.event_31_03","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"PK中队那群人……他们的目的到底是什么？","en":"PK Squadron...  What on earth could their plans be?","ja":"あのスコードロンの連中......奴らの目的は一体何なんだ?"},"kind":"dialogue"},{"uid":"talk.event_31_04#originalText","id":"talk.event_31_04","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"谢谢大家。谢谢你们来GGO的世界。","en":"I would like to thank you everyone for joining us in the GGO world.","ja":"みんな、ありがとうGGOの世界に来てくれて"},"kind":"dialogue"},{"uid":"talk.event_31_05#originalText","id":"talk.event_31_05","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"嗯，我也要选那把剑！还跟桐人的一样呢。","en":"I'll use this sword, too! It matches with Kirito.","ja":"うん、わたしもこの剣にする！キリトくんとおそろいだし"},"kind":"dialogue"},{"uid":"talk.event_31_06#originalText","id":"talk.event_31_06","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"喔，这里就是GGO吗⋯⋯总觉得连空气都很有那种感觉呢！","en":"So this is the GGO world...  You can tell by the smell!","ja":"へえ、ここがGGOか……なんか、匂いまでソレっぽいな！"},"kind":"dialogue"},{"uid":"talk.event_31_07#originalText","id":"talk.event_31_07","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"真的那么过份吗？那些⋯⋯会去PK的人。","en":"Are they really that bad? Those... PK guys.","ja":"そんなにひどいんですか、その……PKする人たちは"},"kind":"dialogue"},{"uid":"talk.event_31_08#originalText","id":"talk.event_31_08","speaker":{"cn":"Subtilizer","en":"Subtilizer","ja":"サトライザー"},"text":{"cn":"⋯⋯⋯⋯","en":"...","ja":"………………"},"kind":"dialogue"},{"uid":"talk.event_32_01#originalText","id":"talk.event_32_01","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这里到底是哪里……？","en":"Where the hell am I...?","ja":"一体、ここはどこなんだ......?"},"kind":"dialogue"},{"uid":"talk.event_32_02#originalText","id":"talk.event_32_02","speaker":{"cn":"白衣少女","en":"Little Girl in White","ja":"白い衣の少女"},"text":{"cn":"来到这里的话，就不必再受苦了吧？","en":"Don't you know?  If you're here, then that means you'll finish without suffering.","ja":"ここにいればもう苦しまずに済むんだよ?"},"kind":"dialogue"},{"uid":"talk.event_32_03#originalText","id":"talk.event_32_03","speaker":{"cn":"谜之剑士","en":"Mysterious Swordsman","ja":"謎の剣士"},"text":{"cn":"之后的路，也不要认输要继续努力啊。","en":"From now on, let's do our best without losing.","ja":"この先も、せいぜい負けずに頑張るんだな"},"kind":"dialogue"},{"uid":"talk.event_32_04#originalText","id":"talk.event_32_04","speaker":{"cn":"拿着锤子的少女","en":"Young Girl With a Hammer","ja":"ハンマーを持った少女"},"text":{"cn":"好啦，快点振作起来！你一直留在这边也没什么好处呀。","en":"Get a hold of yourself! There's no good in you being here forever!","ja":"ほらシャキッとしなさい!あんたはいつまでもここにいて良いはずがないわよ"},"kind":"dialogue"},{"uid":"talk.event_32_05#originalText","id":"talk.event_32_05","speaker":{"cn":"穿着长袍的少女","en":"Young Girl Wearing a Robe","ja":"ローブを着た少女"},"text":{"cn":"你的心，的确是留在这里了。","en":"Certainly, your heart resides here.","ja":"おぬしの心はたしかにここに、残っておるのじゃ"},"kind":"dialogue"},{"uid":"talk.event_32_06_1#originalText","id":"talk.event_32_06_1","speaker":{"cn":"金发青年","en":"Blonde Young Man","ja":"金髪の青年"},"text":{"cn":"好了，快站起来。我们不管几次都会重新振作起来的。","en":"Get up. We don't give up that easy.","ja":"さあ立って僕たちは何度でも立ち上がるんだ"},"kind":"dialogue"},{"uid":"talk.event_32_06_2#originalText","id":"talk.event_32_06_2","speaker":{"cn":"拿着细剑的少女","en":"Young Girl With a Rapier","ja":"細剣を持った少女"},"text":{"cn":"没问题的。是你的话，一定可以继续往前走。","en":"It's fine. If it's you, you'll definitely get ahead.","ja":"大丈夫君ならこの先もきっと進めるよ"},"kind":"dialogue"},{"uid":"talk.event_32_clear1#originalText","id":"talk.event_32_clear1","speaker":{"cn":"黑色装束的少女","en":"Young Girl in Black Attire","ja":"黒装束の少女"},"text":{"cn":"只有现在，我是为了你而唱歌。","en":"I'll only sing for you now.","ja":"今だけはあなたのために歌うよ"},"kind":"dialogue"},{"uid":"talk.event_32_clear2#originalText","id":"talk.event_32_clear2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就算这前方有任何事，我也一定会继续前进！","en":"No matter what stands in my way, I'll keep going forward!","ja":"この先に何があっても進み続けてみせる!"},"kind":"dialogue"},{"uid":"talk.event_33_01#originalText","id":"talk.event_33_01","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"冬至的祭典？喔，这边也有情人节啊。","en":"The Winter Solstice Festival?  Looks like even here they have Valentine's day.","ja":"冬至のお祭り? へえ、こっちにもバレンタインがあるんだな"},"kind":"dialogue"},{"uid":"talk.event_33_02#originalText","id":"talk.event_33_02","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"送莉娜学姊礼物……桐人的想法真的总是让人出乎意料。","en":"A gift for Sortiliena... I'm always surprised with Kirito's thinking!","ja":"リーナ先輩に贈り物なんて……キリトの考えには驚かされっぱなしだよ"},"kind":"dialogue"},{"uid":"talk.event_33_03#originalText","id":"talk.event_33_03","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"桐人会露出怎样的表情呢。呵呵……真让人期待。","en":"I wonder how Kirito will react to my gift. Hehe… I can’t wait.","ja":"キリトのやつ、どんな顔をするかなふふ……楽しみだ"},"kind":"dialogue"},{"uid":"talk.event_34_01#originalText","id":"talk.event_34_01","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"召唤……集成骑士？我吗……？","en":"Summoned? Integrity Knight? Am I really...?","ja":"召喚……整合騎士?私が……?"},"kind":"dialogue"},{"uid":"talk.event_34_02#originalText","id":"talk.event_34_02","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"我只是觉得2和22，可能也是一种缘份。不好意思，说这种无聊的话。","en":"I saw a connection between 2 and 22. My apologies. I said something rather silly.","ja":"2と22、縁があると思ったのだすまぬ、下らぬことを言ってしまったな"},"kind":"dialogue"},{"uid":"talk.event_34_04#originalText","id":"talk.event_34_04","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"难得法那提欧大人准备了跟自己一样的盔甲给我……","en":"A shame, when I got a helmet just like Fanatio's...","ja":"せっかく、ファナティオ様と同じ兜を用意していただいたというのに……"},"kind":"dialogue"},{"uid":"talk.event_34_06#originalText","id":"talk.event_34_06","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"来吧，达基拉！让我见识一下你的实力。","en":"Come at me, Dakira. I will assess your skill.","ja":"かかってこい、ダキラその腕前、私が見極めてやる"},"kind":"dialogue"},{"uid":"talk.event_34_07#originalText","id":"talk.event_34_07","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"你真的以为这样的剑，可以和暗之军队对抗吗！？","en":"Do you honestly think you can stand a chance against the enemy with such shoddy skills?!","ja":"このような剣で、本当に闇の軍勢と戦えると思っているのか!?"},"kind":"dialogue"},{"uid":"talk.event_34_08#originalText","id":"talk.event_34_08","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"四旋剑……","en":"Four Whirling Blades...","ja":"四旋剣……"},"kind":"dialogue"},{"uid":"talk.event_34_10#originalText","id":"talk.event_34_10","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"出发吧，四旋剑！","en":"Be off, Four Whirling Blades!","ja":"ではゆくぞ、四旋剣!"},"kind":"dialogue"},{"uid":"talk.event_34_12#originalText","id":"talk.event_34_12","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"……达基拉还没有醒过来吗？","en":"Is Dakira still asleep?","ja":"……ダキラはまだ目を覚まさぬのか?"},"kind":"dialogue"},{"uid":"talk.event_34_14_1#originalText","id":"talk.event_34_14_1","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"以后也拜托了，四旋剑。你们是我的骄傲。","en":"I am proud of you,  Four Whirling Blades.","ja":"これからも頼りにしているぞ、四旋剣お前たちは、我が誇りだ"},"kind":"dialogue"},{"uid":"talk.event_34_14_2#originalText","id":"talk.event_34_14_2","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"啊啊，法那提欧大人……今后也请让我留在您的身边！","en":"Vice-Commander Fanatio... It will be an  honor to continue to serve by your side!","ja":"ああ、ファナティオ様……今後もお側にお仕えいたします!"},"kind":"dialogue"},{"uid":"talk.event_35_01#originalText","id":"talk.event_35_01","speaker":{"cn":"明日奈","en":"Asuna","ja":"明日奈"},"text":{"cn":"我要去Underworld。","en":"I will go to Underworld.","ja":"わたし、アンダーワールドに行きます"},"kind":"dialogue"},{"uid":"talk.event_35_02#originalText","id":"talk.event_35_02","speaker":{"cn":"明日奈","en":"Asuna","ja":"明日奈"},"text":{"cn":"我想跟桐人说，你已经做了所有你能做的事了。","en":"I want to tell Kirito. That you did everything that you could do.","ja":"キリト君に言ってあげたいんです君はできるかぎりのことをしたんだよ、って"},"kind":"dialogue"},{"uid":"talk.event_35_03#originalText","id":"talk.event_35_03","speaker":{"cn":"明日奈","en":"Asuna","ja":"明日奈"},"text":{"cn":"桐人拯救过我无数次，所以这次轮到我去帮助他了。","en":"Kirito's saved me countless times. So next time, I want to be the one saving him.","ja":"キリトくんは何度もわたしを救ってくれたものだから、今度はわたしが助けに行く"},"kind":"dialogue"},{"uid":"talk.event_35_04#originalText","id":"talk.event_35_04","speaker":{"cn":"明日奈","en":"Asuna","ja":"明日奈"},"text":{"cn":"我有从结衣那里听说他来《ALO》救我时发生的事。桐人那时候真的很辛苦。","en":"This was when you came and rescued me from ALO. Yui told me everything... about how hard things were for you, Kirito.","ja":"《ALO》に助けに来てくれた時の話ユイちゃんが聞かせてくれたよキリトくんが、どんなに大変だったか"},"kind":"dialogue"},{"uid":"talk.event_35_05#originalText","id":"talk.event_35_05","speaker":{"cn":"明日奈","en":"Asuna","ja":"明日奈"},"text":{"cn":"……等一下吧，桐人。我一定会带你回来的！","en":"...Please hold on, Kirito. I will bring you home!","ja":"……待っててね、キリトくん必ず、君を連れて帰るからね!"},"kind":"dialogue"},{"uid":"talk.event_36_01#originalText","id":"talk.event_36_01","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット "},"text":{"cn":"各位！请你们把力量借给我们！","en":"Please, everyone! We need your help!","ja":"お願いみんな!あたしたちに力を貸して!"},"kind":"dialogue"},{"uid":"talk.event_36_02#originalText","id":"talk.event_36_02","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"重要的伙伴陷入危机了，快去帮助他吧！","en":"Our friends are in a pinch! We need to hurry and go help them out!","ja":"大切な仲間の危機なんだ早く助けに行ってやろう!"},"kind":"dialogue"},{"uid":"talk.event_36_03#originalText","id":"talk.event_36_03","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"你等着吧，阿桐。我会去救你的。","en":"Wait up, Kirito! I'm coming to help out!","ja":"待ってろよ、キリの字助けに行ってやっからよ"},"kind":"dialogue"},{"uid":"talk.event_36_04#originalText","id":"talk.event_36_04","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"就算是我，现在也应该变强了一点点。这次轮到我去帮桐人了！","en":"I think I've gotten a little stronger! Next time, it'll be the one saving Kirito!","ja":"あたしだって少しは強くなったんです今度はあたしがキリトさんを助けます!"},"kind":"dialogue"},{"uid":"talk.event_36_05#originalText","id":"talk.event_36_05","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット "},"text":{"cn":"我会去救你⋯⋯好好等着喔。","en":"I'm on my way to help... Wait for me!","ja":"今助けに行くからね……ちゃんと待ってなさいよ"},"kind":"dialogue"},{"uid":"talk.event_37_01#originalText","id":"talk.event_37_01","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ "},"text":{"cn":"⋯⋯可以的话我也不想跟人类碰面。因为我会变得想要斩人。","en":"...If possible, I'd rather avoid meeting anyone. I'll want to cut their head off, otherwise.","ja":"……できれば人と会いたくない斬りたくなってしまうから"},"kind":"dialogue"},{"uid":"talk.event_37_02#originalText","id":"talk.event_37_02","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ "},"text":{"cn":"什么也能斩开的剑⋯⋯那种东西，我⋯⋯","en":"A sword that can cut...  I...","ja":"何だろうと斬れる剣……そんなもの、私は……"},"kind":"dialogue"},{"uid":"talk.event_37_03#originalText","id":"talk.event_37_03","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"剩下来的就只有黑色的百合花。就算是这样，神圣力好像也还很充足。","en":"The only thing remaining are those black lilies. Still, my Sacred Power is more than enough.","ja":"残っていたのは黒い百合の花だけそれでも、神聖力は十分のようね"},"kind":"dialogue"},{"uid":"talk.event_37_04#originalText","id":"talk.event_37_04","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"跟那家伙来到央都，也已经2年了。时间过得真快。","en":"It's already been 2 years since I came to Centoria with him. Time sure flies.","ja":"あいつと央都にやってきて、もう2年あっという間だったな"},"kind":"dialogue"},{"uid":"talk.event_37_05#originalText","id":"talk.event_37_05","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"所谓的胜负，当然会有胜也有负。真想一直这样较量下去。","en":"Win some, lose some. For however long, I want to keep competing like this.","ja":"勝負は勝ったり負けたりだこのまま、いつまでも競い合っていきたい"},"kind":"dialogue"},{"uid":"talk.event_37_clear_01#originalText","id":"talk.event_37_clear_01","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"就算是这样，我也⋯⋯因为那就是，那家伙的梦想⋯⋯","en":"Still, to be an Integrity Knight...  That was his dream...","ja":"それでも、僕は整合騎士に……それがあいつのゆめだったから……"},"kind":"dialogue"},{"uid":"talk.event_38_01#originalText","id":"talk.event_38_01","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"一定要回去……回到那个我该回去的地方……","en":"I need to return... To the place where I need to be...","ja":"帰らなければ……どこかへ俺のいるべき場所へ……"},"kind":"dialogue"},{"uid":"talk.event_38_02#originalText","id":"talk.event_38_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那个人呢……？那个人到哪里去了？","en":"That child...? Where did she run off to?","ja":"あの子は……?あの子はどこへ行ったんだ?"},"kind":"dialogue"},{"uid":"talk.event_38_03#originalText","id":"talk.event_38_03","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我……我并没有感到绝望！为了要守护重要的人！！","en":"I'm... I'm not hopeless! This is to protect the person I care for!","ja":"俺は……俺は絶望なんてしない!大事な人を守るために!!"},"kind":"dialogue"},{"uid":"talk.event_38_04#originalText","id":"talk.event_38_04","speaker":{"cn":"黑发的少女","en":"Black Haired Girl","ja":"黒髪の少女"},"text":{"cn":"你又再次拯救了我呢，爸爸。就和那个时候一样。","en":"Looks like you saved me again, Papa. Just like that time.","ja":"またわたしを助けてくれたんですね、パパあの時と同じように"},"kind":"dialogue"},{"uid":"talk.event_38_05#originalText","id":"talk.event_38_05","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"捆绑着我的，不是毒也不是魔力，而是我脆弱的内心！","en":"What binds me isn't poison or magic! It's the weakness in my heart!","ja":"縛っているのは、毒でも魔力でもない俺の心の弱さだ!"},"kind":"dialogue"},{"uid":"talk.event_38_06#originalText","id":"talk.event_38_06","speaker":{"cn":"拿着细剑的少女","en":"Young Girl With a Rapier","ja":"細剣を持った少女"},"text":{"cn":"我在那个地方等着你喔。我们两人的，回忆的地方……","en":"I will be waiting there. The place in our memories...","ja":"あの場所で待ってるよふたりの、思い出の場所で……"},"kind":"dialogue"},{"uid":"talk.event_38_clear1#originalText","id":"talk.event_38_clear1","speaker":{"cn":"黑发的少女","en":"Black Haired Girl","ja":"黒髪の少女"},"text":{"cn":"欢迎回来，爸爸！","en":"Welcome back, Papa!","ja":"おかえりなさい、パパ!"},"kind":"dialogue"},{"uid":"talk.event_38_clear2#originalText","id":"talk.event_38_clear2","speaker":{"cn":"拿着细剑的少女","en":"Young Girl With a Rapier","ja":"細剣を持った少女"},"text":{"cn":"我一直很想见你啊。","en":"I've been wanting to meet you this whole time.","ja":"ずっと、会いたかったよ"},"kind":"dialogue"},{"uid":"talk.event_42_01#originalText","id":"talk.event_42_01","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"有话想跟我说……而且，是像这样只有两个人的时候说，到底是什么事呢。","en":"A talk with me... But what kind of talk would that be with just the two of us?","ja":"私に話を……しかも、こうしてふたりきりでどのようなお話なのだろうか"},"kind":"dialogue"},{"uid":"talk.event_42_02#originalText","id":"talk.event_42_02","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"法那提欧从第一次见面的时候，就没有变过，是最高洁、最有人情味的集成骑士。","en":"Fanatio hasn't changed one bit since we first met. She is the most noble and compassionate Integrity Knight there is.","ja":"ファナティオは出会った時から全く変わってねぇ一番高潔で、情け深い整合騎士だ"},"kind":"dialogue"},{"uid":"talk.event_42_03#originalText","id":"talk.event_42_03","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"阁下和第一次见面时也没有任何改变。也许会抱怨很多事，但每次到最后都会负上所有责任。","en":"His excellency hasn't changed since the day I first met  him. He's the kind of person who would say a lot, but in the end he still takes responsibility for everything.","ja":"閣下は出会った時から変わっていませんね。口ではいろいろ言いながら最後は全ての責任を取られるのです"},"kind":"dialogue"},{"uid":"talk.event_42_04#originalText","id":"talk.event_42_04","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"和阁下一起奋战的日子，到了现在也一直深深刻印在我的身体以及我的脑内。","en":"The days running around with his excellency are still ingrained in my mind.","ja":"閣下と駆け抜けた日々は今もこの身に、脳裏に、焼き付いているのだ"},"kind":"dialogue"},{"uid":"talk.event_42_05#originalText","id":"talk.event_42_05","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"为了不让今天的泪水流到明天，集成骑士团必须变得更强。","en":"As Integrity Knights, we need to get even stronger so that we don't shed the same tears as today.","ja":"今日の涙を明日また流さないために整合騎士団は、もっと強くあらねばならない"},"kind":"dialogue"},{"uid":"talk.event_22_01#originalText","id":"talk.event_22_01","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"我说涅尔，要不要去泡澡？","en":"Hey, Nel, want to take a bath?","ja":"ねぇねぇ、お風呂行かない、ネル?"},"kind":"dialogue"},{"uid":"talk.event_22_02#originalText","id":"talk.event_22_02","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"桐人先生跟尤吉欧先生……他们看起来都是很温柔的一般人呢。","en":"Kirito and Eugeo... They seemed like nice, normal boys to me.","ja":"キリトさんと、ユージオさん……普通の、優しそうな人でしたね"},"kind":"dialogue"},{"uid":"talk.event_22_03#originalText","id":"talk.event_22_03","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"泡澡啊……真是风雅呢。我已经一阵子没泡了。","en":"The bath, eh? That sounds lovely. I haven't had one in ages.","ja":"風呂か……ずいぶん優雅だなオレはしばらく入ってねぇや"},"kind":"dialogue"},{"uid":"talk.event_22_04#originalText","id":"talk.event_22_04","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"我好像有了一些改变，不，应该说是被他们改变了吧。","en":"And I felt something change within me. No. Perhaps I should say I made the change myself.","ja":"私の中で、何かが変わったのだいや、変えられてしまった、と言うべきかな"},"kind":"dialogue"},{"uid":"talk.event_22_05#originalText","id":"talk.event_22_05","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"逃避上战场征伐的人，根本没有资格当骑士！","en":"How can you call yourself a knight if you refuse to go into battle?","ja":"自ら進んで戦場に立たずして何が騎士か!"},"kind":"dialogue"},{"uid":"talk.event_40_01#originalText","id":"talk.event_40_01","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我很开心有缇洁在我的身边。","en":"I'm glad you are here, Tiese!","ja":"私、ティーゼがいてくれてよかった"},"kind":"dialogue"},{"uid":"talk.event_40_02#originalText","id":"talk.event_40_02","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"走吧，罗妮耶，去学长们那里！","en":"Let's go, Ronie! Where Kirito and Eugeo are!","ja":"行こう、ロニエ先輩たちのところに!"},"kind":"dialogue"},{"uid":"talk.event_40_03#originalText","id":"talk.event_40_03","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"如果人界陷入危机，从军是贵族的责任。","en":"If a crisis were to happen in the Human Empire, it falls upon the nobles to join the army.","ja":"人界の危機となれば従軍は貴族の務めであります"},"kind":"dialogue"},{"uid":"talk.event_40_04#originalText","id":"talk.event_40_04","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"……看来他们既受前辈照顾，也受后辈爱戴。","en":"Those boys were blessed... from above and below.","ja":"……上にも下にも恵まれてたんだなあいつらは"},"kind":"dialogue"},{"uid":"talk.event_40_05#originalText","id":"talk.event_40_05","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"呵，看来好事之徒都聚在一起了。","en":"Hm... Looks like something curious has arrived.","ja":"ふっ、物好きがそろったということか"},"kind":"dialogue"},{"uid":"talk.event_39_01#originalText","id":"talk.event_39_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"没事的，放心吧。我一定不会跟任何人说爱丽丝在这里的。","en":"Don't worry about it. No one will ever mention that Alice is here. No one.","ja":"大丈夫、安心してアリスがここにいることは決して誰にも言わない"},"kind":"dialogue"},{"uid":"talk.event_39_02#originalText","id":"talk.event_39_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不用那么拘紧，怎么了？","en":"You don't have to be so polite with me. What happened?","ja":"そんなにかしこまらないでいいよどうしたの?"},"kind":"dialogue"},{"uid":"talk.event_39_03#originalText","id":"talk.event_39_03","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……要是到了我们需要投入所有人的状况的话，我想那一定是非常重要的时刻吧……","en":"...If we're all thrown into the mix, that will be the moment of truth...","ja":"……あたしたちが総員投入されるっていう状態にもしなったらかなり正念場だけどね……"},"kind":"dialogue"},{"uid":"talk.event_39_04#originalText","id":"talk.event_39_04","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"……独立部队吗。是打算从南边的洞穴攻过来吗？","en":"...A detached unit? Are they going to attack from the southern caves?","ja":"……別働隊か南の洞窟から攻めてくるつもりかな?"},"kind":"dialogue"},{"uid":"talk.event_39_05#originalText","id":"talk.event_39_05","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"别看我这样，我也是集成骑士喔？没事的，我不会乱来。","en":"Even if you look at me like that, you do know I'm still an Integrity Knight, right? Don't worry, I won't get reckless.","ja":"こう見えても整合騎士なんだよ?大丈夫、無茶な戦い方はしないから"},"kind":"dialogue"},{"uid":"talk.event_48_01#originalText","id":"talk.event_48_01","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"一定要救出桐人。因为我们还没分出胜负啊。","en":"I will save Kirito! Because we are far from being finished!","ja":"絶対にキリトを助けるだって私たちの決着はまだついていないんだから"},"kind":"dialogue"},{"uid":"talk.event_48_02#originalText","id":"talk.event_48_02","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"对着我竟然敢让步，真是勇气可加。","en":"You have some nerves to put a handicap on me!","ja":"私に対してハンデを付けるなんていい度胸をしているじゃない"},"kind":"dialogue"},{"uid":"talk.event_45_01#originalText","id":"talk.event_45_01","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"我只是想要去做现在的我能做到的事……","en":"What I can do now... Is what I will do.","ja":"今の僕にできること……それをやるだけだ"},"kind":"dialogue"},{"uid":"talk.event_45_02#originalText","id":"talk.event_45_02","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"瑛二是很强的。我可是一直都知道喔。","en":"Eiji is very strong. I of all people would know that.","ja":"エイジはすごく強いよあたしはちゃんと知ってるんだから"},"kind":"dialogue"},{"uid":"talk.event_45_03#originalText","id":"talk.event_45_03","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"为什么每个男人都是那样的呢。明明再直率一点就好了嘛。","en":"Why do guys have to be like that? If only they could be a little more honest.","ja":"男って、どうしてみんなああなのかしらもうちょっと素直になればいいのに"},"kind":"dialogue"},{"uid":"talk.event_45_04#originalText","id":"talk.event_45_04","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你的心情，我也有点明白。如果是我，我应该会忍受不了……","en":"I understand how you feel, just a little bit. If it were me, I for sure wouldn't be able to stand it...","ja":"あなたの気持ち、あたしには少しわかります。あたしならきっと耐えられない……"},"kind":"dialogue"},{"uid":"talk.event_45_05#originalText","id":"talk.event_45_05","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"我在身旁的YUNA也是AI。一想到这点，我就会觉得很心痛。","en":"Even Yuna, who's by my side, is an AI. When I think of that, my chest tightens up.","ja":"僕の傍にいるユナも、AIだそう考えると、胸が締め付けられる"},"kind":"dialogue"},{"uid":"talk.event_41_01#originalText","id":"talk.event_41_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"艾尔多利耶……要是死了就什么都做不了啊。你太耍帅了。","en":"Eldrie...If you died, it would lead to nothing. Stop acting so cool.","ja":"エルドリエ……死んじゃったら何にもならないでしょかっこつけすぎだよ"},"kind":"dialogue"},{"uid":"talk.event_41_02#originalText","id":"talk.event_41_02","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"爱丽丝现在有点事情在忙。说是有关桐人很重要的事呢。","en":"Alice is taking it all in. She has something important to talk to Kirito about.","ja":"アリスは、ちょっと取り込み中でなキリトのことで、大事な大事な話があるんだとよ"},"kind":"dialogue"},{"uid":"talk.event_41_03#originalText","id":"talk.event_41_03","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"看起来好像没有战斗发生……总觉得有点奇怪。","en":"From a glance, it doesn't look like there is any combat...Something is off.","ja":"一見戦闘は行われてないように見えるけど……なんかおかしいわね"},"kind":"dialogue"},{"uid":"talk.event_41_04#originalText","id":"talk.event_41_04","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"我们也想去桐人那里！因为我们也有足够实力去战斗的！","en":"We also want to join Kirito! Because we're ready to fight!","ja":"あたしたちも、キリトのところに行きたい!もうちゃんと戦えるんだから!"},"kind":"dialogue"},{"uid":"talk.event_41_05#originalText","id":"talk.event_41_05","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"我觉得只要去了桐人那里就会明白到底在发生什么事……一定可以明白一些重要的事。","en":"I feel like, if I can just join Kirito I'll understand something... Something important.","ja":"キリトさんの所に行けば何かわかる気がするんです……大事なことが、きっと"},"kind":"dialogue"},{"uid":"talk.event_43_01#originalText","id":"talk.event_43_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"爱丽丝打从心底信任着那家伙呢。我有点嫉妒了。","en":"I guess Alice really does trust that person from the bottom of her heart. That makes me a little jealous!","ja":"アリスは心の底からアイツのことを信用してるのねちょっとだけ、妬けちゃうな"},"kind":"dialogue"},{"uid":"talk.event_43_02#originalText","id":"talk.event_43_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今后，为了人界和黑暗领域不再有战争发生，我有些事希望你做的。","en":"There is something I want you to do to prevent a war happening between the Human Empire and Dark Territory in the future.","ja":"今後、人界とダークテリトリーの戦争を起こさないためにもあんたにやってほしいことがあるんだ"},"kind":"dialogue"},{"uid":"talk.event_43_03#originalText","id":"talk.event_43_03","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"没想到黑暗领域的女孩子也挺可爱的嘛。莉琵雅也很可爱。","en":"Girls from the Dark Territory are surprisingly cute! I mean, that Lipia was a real looker!","ja":"ダークテリトリーの女の子も案外可愛いよねリピアちゃんけっこう可愛かったし"},"kind":"dialogue"},{"uid":"talk.event_43_04#originalText","id":"talk.event_43_04","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"该带什么花去黑暗领域好呢。去问问人好了。","en":"What would be a good flower to offer to the Dark Territory? I wonder who I should ask.","ja":"ダークテリトリーで手向ける花ってどういうお花がいいのかな誰に訊いてみよう"},"kind":"dialogue"},{"uid":"talk.event_43_05#originalText","id":"talk.event_43_05","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好了～马上就飞到了黑暗领域的温泉！要是真的有温泉还真想进去泡一下啊～","en":"Well then! How about going to a hot spring in the Dark Territory! If there is one, I want to give it a try for sure.","ja":"さーて、ひとっ飛びして来ようっとダークテリトリーで温泉! なんてあったら入ってみたいんだけどなー"},"kind":"dialogue"},{"uid":"talk.event_46_01#originalText","id":"talk.event_46_01","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"剑的练习也很开心，但是我有时也想跟朋友出去玩啊。","en":"Sword training is fun, but sometimes it's nice hanging out with friends.","ja":"剣の稽古は楽しいけどたまにはあたしだって友だちと遊びたいな"},"kind":"dialogue"},{"uid":"talk.event_46_02#originalText","id":"talk.event_46_02","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学剑也是休特里涅家的义务吗……","en":"Studying the sword is the duty of the Shtolienen  family. I wonder why that is...","ja":"剣を学ぶことがシュトリーネン家の務めってどういうことかしら……"},"kind":"dialogue"},{"uid":"talk.event_46_03#originalText","id":"talk.event_46_03","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我不是很擅长上级贵族的人，因为他们总是说话很大声又摆架子。","en":"I'm not that great around high-ranking nobles. They're always putting on a show.","ja":"上級貴族の人って、少し苦手なのいつも大声で威張ってくるから"},"kind":"dialogue"},{"uid":"talk.event_46_04#originalText","id":"talk.event_46_04","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"那也是贵族的使命吗？如果是，那上级贵族的人们是……？","en":"Is that the duty of nobles? How about high-ranking nobles then...?","ja":"それが貴族の使命なの?だったら上級貴族の人たちは……?"},"kind":"dialogue"},{"uid":"talk.event_46_05#originalText","id":"talk.event_46_05","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"难道以前父亲所说的人就是……","en":"Could it be, the person whom my father spoke of long ago...?","ja":"もしかして昔父が言っていた人って……"},"kind":"dialogue"},{"uid":"talk.event_49_01#originalText","id":"talk.event_49_01","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"终于到实战了吗，真让人急不及待。","en":"Finally, a real battle! I've been waiting for this!","ja":"ようやく実戦かもっと早く戦いたかったぜ"},"kind":"dialogue"},{"uid":"talk.event_49_02#originalText","id":"talk.event_49_02","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"就算成为了冠军也不能就此满足。要变得更加更加强才行！","en":"Becoming a champion doesn't mean that I'm satisfied at all. It means that I need to get even stronger!","ja":"チャンピオンになったって満足なんてしねえ。もっともっと強くならなきゃなんねえんだよ!"},"kind":"dialogue"},{"uid":"talk.event_49_03#originalText","id":"talk.event_49_03","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"不论对手是谁，拳斗士公会是绝对不会输给其他种族的。","en":"The boxers guild will never lose to any other tribe! No matter who their opponent is.","ja":"拳闘士ギルドは他の種族には絶対に負けねえたとえ相手が誰であってもな"},"kind":"dialogue"},{"uid":"talk.event_49_04#originalText","id":"talk.event_49_04","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"总有一天，我会遇到一个会破坏我的对手吧。为了迎接那一天的来临，我一定要不断的锻炼自己。","en":"Someday, I will face an opponent who can destroy me. That's why I continue to train.","ja":"いつか、俺を壊すような相手に巡り会うだろうそれに向けて鍛錬を続けるんだ"},"kind":"dialogue"},{"uid":"talk.event_49_05#originalText","id":"talk.event_49_05","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"暗黑骑士夏斯达……跟那家伙说话总会打乱我的步调。","en":"Dark Knight Shasta... I go crazy whenever I talk to him!","ja":"暗黒騎士シャスター……奴と話すと調子が狂うぜ"},"kind":"dialogue"},{"uid":"talk.event_44_01#originalText","id":"talk.event_44_01","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"自己想要守护的人其实也是很坚强的存在。这是那个黑色剑士教会我的。","en":"Those who I thought needed protection are actually the strong ones. That is what the black swordsman taught me.","ja":"庇護すべきだと思っていた人間も本当は強い存在なのだあの黒い剣士が、それを教えてくれた"},"kind":"dialogue"},{"uid":"talk.event_44_02#originalText","id":"talk.event_44_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那个男人竟然打倒了最高司祭大人……不枉他是爱丽丝所信任的人。","en":"This man defeated the High pontifex ...No wonder Alice trusts him.","ja":"最高司祭様を倒しちゃうなんてあの男……アリスが信用するだけのことはあるわね"},"kind":"dialogue"},{"uid":"talk.event_44_03#originalText","id":"talk.event_44_03","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"那个男人……经常跟爱丽丝大人黏在一起！爱丽丝大人也是，为什么会为那个男人做到这个地步！","en":"Alice...She's already sticking around with this guy! Why is she so attached to this man!?","ja":"あの男……常にアリス様にべったりとくっついて! アリス様もなぜあの男にはあれほどまで!"},"kind":"dialogue"},{"uid":"talk.event_44_04#originalText","id":"talk.event_44_04","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……因为战争，所以让我醒过来了？我又要斩人了呢……","en":"...Did you wake me up because there is a war? I guess I will be killing people again...","ja":"……戦争だから、目覚させられた?私、また人を斬るのね……"},"kind":"dialogue"},{"uid":"talk.event_44_05#originalText","id":"talk.event_44_05","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"就算是我这种不中用的家伙，也能帮上一点忙。虽然害怕，但必须战斗……","en":"Even if I'm a good for nothing, if I can help just a little bit I will. It's scary, but I need to fight...","ja":"僕のような出来損ないでも、少しは役に立つんだ怖いけど、戦わなくちゃ……"},"kind":"dialogue"},{"uid":"talk.event_50_01#originalText","id":"talk.event_50_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我一定会治好梅雅丽的脚。因为我知道，只要诚心许愿，愿望一定会成真！","en":"Mary's leg will definitely heal. Because I know that, if you truly believe in something, then it will always come true!","ja":"メアリの足は必ず治る強く信じれば、必ず叶うってあたしは知ってるんだから!"},"kind":"dialogue"},{"uid":"talk.event_50_02#originalText","id":"talk.event_50_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我听过一个传说，住在东边尽头的龙是无所不知的。这样的话，牠一定也知道治好梅雅丽的脚的方法！","en":"I heard about a legend of a dragon residing in the far east who had knowledge on everything. If the legends are true, then it must know of a way to heal Mary's leg!","ja":"東の果てに住む竜は、何でも知ってるという言い伝えを聞いた。ならメアリの足を治す方法も、きっと!"},"kind":"dialogue"},{"uid":"talk.event_50_03#originalText","id":"talk.event_50_03","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"姊姊在旅行的时候总会遇上危险……我好担心她喔。","en":"I'm always worried about the dangers my sister encounters in the places she goes to...","ja":"お姉ちゃん、いつも旅先で危ない目に遭って……心配だなあ"},"kind":"dialogue"},{"uid":"talk.event_50_04#originalText","id":"talk.event_50_04","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"姊姊每次回来，我都会跟她一起洗澡。一起洗澡会让我跟姊姊都感到幸福。","en":"Whenever my sister comes back, we always take a bath together. That way, we're both happy!","ja":"お姉ちゃんが帰ってきた時は、絶対に一緒にお風呂に入るの。そうするとわたしもお姉ちゃんも幸せなんだ"},"kind":"dialogue"},{"uid":"talk.event_51_01#originalText","id":"talk.event_51_01","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"说起来，我记得有个女生曾经对我说过「我会成为你专属的冶炼师」……","en":"Speaking of which, there was a girl who said that she would be a 'blacksmith'...","ja":"そう言えば、俺には「専属鍛冶師になる」と言ってくれた女の子がいるんだよな……"},"kind":"dialogue"},{"uid":"talk.event_51_02#originalText","id":"talk.event_51_02","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"看来基家斯西达的树枝将会变成一把很强的剑呢。就跟卡利塔爷爷所说的一样。","en":"Looks like the Gigas Cedar branch could be used for a powerful sword. Just like what Garitta said.","ja":"ギガスシダーの枝すごい剣になりそうだねガリッタさんの言ったとおりだよ"},"kind":"dialogue"},{"uid":"talk.event_51_03#originalText","id":"talk.event_51_03","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"萨多雷的天职明明是金属工艺师，但店里放的全都是装备。简直就像是冶炼师嘛。","en":"Sadore's sacred task is to be a goldsmith, but all you can see is armor at his shop. He's really a blacksmith.","ja":"サードレさんの店、天職が金細工師なのに置いてあるのは武具ばっかりだな。まるで鍛冶師だよ"},"kind":"dialogue"},{"uid":"talk.event_51_04#originalText","id":"talk.event_51_04","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我感觉已经很久没跟现实世界的大家见面了。不知道大家过得好不好……","en":"I feel like it's been a long time since I've last met everyone in the real world... I wonder how everyone is doing?","ja":"現実世界のみんなと会えなくなってもうずいぶん経った気がするみんな元気にしているかな……"},"kind":"dialogue"},{"uid":"talk.event_51_05#originalText","id":"talk.event_51_05","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人看起来很奇怪。难道是因为自己没有记忆而在烦恼吗……我想帮他一把。","en":"There's something off about Kirito. Perhaps he's worried about not having his own memories... I want to try my best to help him out.","ja":"キリトの様子が変だ。もしかして自分に記憶が無いことを悩んでいるのかな……力になってあげたい"},"kind":"dialogue"},{"uid":"talk.event_52_01#originalText","id":"talk.event_52_01","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"要赶快到哥哥的身边才行……！","en":"I need to get to meet Kirito as soon as possible...!","ja":"一刻も早くお兄ちゃんの所に行かなくちゃ……!"},"kind":"dialogue"},{"uid":"talk.event_52_02#originalText","id":"talk.event_52_02","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"真没想到在这种地方居然会有这么美好的相遇。","en":"I didn't think that I would meet someone that special in a place like this.","ja":"こんな場所であんな素敵な出会いがあるなんて、思わなかったな"},"kind":"dialogue"},{"uid":"talk.event_52_03#originalText","id":"talk.event_52_03","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"竟然对重要的人做出那种事……真的无法原谅！","en":"To say such an awful thing to someone I care about... Is unforgivable!","ja":"大切な人にあんな酷いことするなんて……絶対に許せないよ!"},"kind":"dialogue"},{"uid":"talk.event_52_04#originalText","id":"talk.event_52_04","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"能够像这样对话的话，外表根本就没有关系吧。我们都是人类。","en":"Since we can exchange words like this,  it has nothing to do with appearance.  We're both human.","ja":"こうして言葉を交わせるんだから外見なんて関係ないでしょ同じ人間だよ"},"kind":"dialogue"},{"uid":"talk.event_52_05#originalText","id":"talk.event_52_05","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"就是因为这样所以我才不喜欢用新机器～我明明想快点到哥哥身边的！","en":"It's because of this that I hate these new gadgets!  I want to see Kirito  as soon as possible!","ja":"これだから、新品の機械って嫌いなんだよー。早くお兄ちゃんのところに行きたいのに!"},"kind":"dialogue"},{"uid":"talk.event_47_01#originalText","id":"talk.event_47_01","speaker":{"cn":"???","en":"???","ja":"？？？"},"text":{"cn":"一切都从这里开始。在陷入绝望的玩家之中，你独自一人踏上为了生存的道路。","en":"This is where it all started. Among all of the players who trembled in despair, you started on your lone path to stay alive.","ja":"すべてはここから始まった絶望に震えるプレイヤーの中で、君はひとり、生きるための道を走り始めた"},"kind":"dialogue"},{"uid":"talk.event_47_02#originalText","id":"talk.event_47_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"虽然记忆有点模糊，但我确实记得，那个奶油和炖肉的味道，和她一起吃过的食物的味道和气味。","en":"Not clearly, but of course—I remember. The taste of the cream and stew, the taste and smell of the meal I shared with her...","ja":"はっきりではないけど、でも確かに覚えている。クリームやシチューの味彼女と一緒に食べた食事の味や匂いを"},"kind":"dialogue"},{"uid":"talk.event_47_03#originalText","id":"talk.event_47_03","speaker":{"cn":"拿着细剑的少女","en":"Young Girl With a Rapier","ja":"細剣を持った少女"},"text":{"cn":"你总是拯救了我……也拯救了大家。这次轮到我来帮你了！","en":"You got me... And you saved everyone! Next time I'll be saving you!","ja":"君はいつだってわたしを……そしてみんなを助けてくれた今度はわたしが助ける番だよ!"},"kind":"dialogue"},{"uid":"talk.event_47_04#originalText","id":"talk.event_47_04","speaker":{"cn":"拿着盾牌的骑士","en":"Shield Knight","ja":"盾を持った騎士"},"text":{"cn":"再展现一次超越系统的力量吧……你要再次站起来。","en":"A power that surpasses the system... Show me one more time. Get up!","ja":"システムを超える力……もう一度、見せてくれ立ち上がるんだ"},"kind":"dialogue"},{"uid":"talk.event_ch13_01#originalText","id":"talk.event_ch13_01","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"姊姊和桐人就由我……我会永远……","en":"I will take care of you and Kirito... forever.","ja":"姉さまとキリトは、あたしが……あたしが、ずっと……"},"kind":"dialogue"},{"uid":"talk.event_ch13_02#originalText","id":"talk.event_ch13_02","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"这是公理教会成立后最为紧急的事态。助我一臂之力吧。","en":"The Axiom Church is in trouble! I need your help!","ja":"公理教会始まって以来の緊急事態だオレに力を貸してくれ"},"kind":"dialogue"}]};
